"""Settings page for provider quota and frontend API diagnostics."""

import streamlit as st

from components.quota import render_quota_dashboard
from services.quota_service import get_quota_service
from utils.auth_session import require_auth


user = require_auth()

st.title("Settings")
st.caption(f"Provider health and quota monitoring - Signed in as {user.full_name}")

quota_tab, handling_tab = st.tabs(["API quota", "Error handling"])

with quota_tab:
    st.subheader("Provider quota")
    st.info(
        "Preview data is generated by the frontend mock service. It will be replaced "
        "by the backend quota endpoint when available."
    )
    try:
        quota_service = get_quota_service()
        quotas = quota_service.list_quotas()
    except (RuntimeError, ValueError) as exc:
        st.error(str(exc))
    else:
        render_quota_dashboard(quotas)
        decision = quota_service.can_execute()
        if decision.allowed:
            st.success("AI requests are currently allowed.")
        else:
            st.error(decision.reason or "AI requests are currently blocked.")

with handling_tab:
    st.subheader("Frontend error policy")
    st.markdown(
        """
        - Validation errors are shown next to the affected input.
        - Expired sessions redirect users to the login page.
        - Rate-limit errors display the provider reset time.
        - Network, timeout, and temporary server errors can be retried.
        - Credentials, access tokens, and raw tracebacks are never shown.
        """
    )
